import React from 'react';
import { Routes, Route, useLocation } from 'react-router-dom';
import { AnimatePresence } from 'framer-motion';
import { AuthProvider } from './context/AuthContext';
import { ThemeProvider } from './context/ThemeContext';
import Navbar from './components/layout/Navbar';
import Footer from './components/layout/Footer';
import Home from './pages/Home';
import About from './pages/About';
import Courses from './pages/Courses';
import CourseDetail from './pages/CourseDetail';
import Contact from './pages/Contact';
import Login from './pages/Login';
import RegisterStudent from './pages/RegisterStudent';
import RegisterTeacher from './pages/RegisterTeacher';
import AdminDashboard from './pages/dashboard/admin/AdminDashboard';
import TeacherDashboard from './pages/dashboard/teacher/TeacherDashboard';
import StudentDashboard from './pages/dashboard/student/StudentDashboard';
import PrivateRoute from './routes/PrivateRoute';
import AdminRoute from './routes/AdminRoute';
import TeacherRoute from './routes/TeacherRoute';
import StudentRoute from './routes/StudentRoute';
import NotFound from './pages/NotFound';

function App() {
  const location = useLocation();
  
  return (
    <ThemeProvider>
      <AuthProvider>
        <div className="flex flex-col min-h-screen bg-background-light dark:bg-slate-900 text-gray-900 dark:text-gray-50 transition-colors duration-300 overflow-hidden">
          {/* Decorative elements */}
          <div className="fixed pointer-events-none">
            {/* Top right blob */}
            <div className="decoration-blob w-72 h-72 bg-primary/10 dark:bg-primary/5 top-0 right-0 -translate-y-1/4 translate-x-1/4" />
            
            {/* Bottom left blob */}
            <div className="decoration-blob w-96 h-96 bg-accent/10 dark:bg-accent/5 bottom-0 left-0 translate-y-1/3 -translate-x-1/3" />
            
            {/* Middle right blob */}
            <div className="decoration-blob w-64 h-64 bg-accent-secondary/10 dark:bg-accent-secondary/5 top-1/2 right-0 -translate-y-1/2 translate-x-1/3 animate-scale-slow" />
            
            {/* Center small blob */}
            <div className="decoration-blob w-20 h-20 bg-accent-tertiary/20 dark:bg-accent-tertiary/10 top-1/3 left-1/2 -translate-x-1/2 animate-pulse-slow" />
          </div>

          <Navbar />
          <main className="flex-grow">
            <AnimatePresence mode="wait">
              <Routes location={location} key={location.pathname}>
                {/* Public Routes */}
                <Route path="/" element={<Home />} />
                <Route path="/about" element={<About />} />
                <Route path="/courses" element={<Courses />} />
                <Route path="/courses/:id" element={<CourseDetail />} />
                <Route path="/contact" element={<Contact />} />
                <Route path="/login" element={<Login />} />
                <Route path="/register/student" element={<RegisterStudent />} />
                <Route path="/register/teacher" element={<RegisterTeacher />} />
                
                {/* Protected Routes */}
                <Route path="/dashboard" element={<PrivateRoute />}>
                  <Route path="admin/*" element={<AdminRoute />}>
                    <Route path="" element={<AdminDashboard />} />
                  </Route>
                  <Route path="teacher/*" element={<TeacherRoute />}>
                    <Route path="" element={<TeacherDashboard />} />
                  </Route>
                  <Route path="student/*" element={<StudentRoute />}>
                    <Route path="" element={<StudentDashboard />} />
                  </Route>
                </Route>
                
                {/* Not Found */}
                <Route path="*" element={<NotFound />} />
              </Routes>
            </AnimatePresence>
          </main>
          <Footer />
        </div>
      </AuthProvider>
    </ThemeProvider>
  );
}

export default App;
